import logo from './logo.svg';
import './App.css';
import React, { useEffect } from 'react';
import { useState } from 'react';

function MyproccessBar({value}) {
  const [filled, setFilled] = useState(0);

  useEffect(() => {
    if (filled < value) {
      const timer = setTimeout(() => {
        setFilled((prev) => prev + 5);
      }, 50);

      return () => clearTimeout(timer);
    }
  }, [filled]);

  return (
    <div className="prossessbar">
      <div
        style={{
          height: "100%",
          width: `${filled}%`,
          backgroundColor: "purple",
          transition: "width 0.5s",
        }}
      ></div>

      <span className="my-proccess">
        {filled}%
      </span>
    </div>
  );
}

function Skills(){
  return(
    <div className='Skills'> 
    <>
    <h1>skills</h1>
    <div className='Back-End'>
    <h2>Back End</h2>
    <p>PHP</p>
    <MyproccessBar value={30}/>
    </div>
    <div className='Databases'>
    <h2>Databases</h2>
    <p>MySQL</p>
    <MyproccessBar value={60}/>
    </div>
    <div className='Front-End'>
    <h2>Front End</h2>
    <p>html</p>
    <MyproccessBar value={90}/>
    <p>css</p>
    <MyproccessBar value={90}/>
    <p>React</p>
    <MyproccessBar value={30}/> 
    </div>
    <div className='Tools'>
    <h2>Tools</h2>  
    <p>Git</p>
    <MyproccessBar value={80}/>  
    <p>Docker</p>
    <MyproccessBar value={70}/>
    <p>LaTeX</p>
    <MyproccessBar value={95}/>  
    <h3>Wordpress</h3>
    <MyproccessBar value={95}/>
    </div>
    <div className='OS'>
    <h2>Operating Systems</h2>
    <p>Debian</p>
    <MyproccessBar value={95}/> 
    <p>Kali</p>
    <MyproccessBar value={95}/>
    <p>Parrot</p>
    <MyproccessBar value={95}/>
    <p>freeBSD</p>
    <MyproccessBar value={50}/>
    <p>Windows/DOS</p>
    <MyproccessBar value={95}/>
    </div>
    <div className='Developing'>
    <h2>Developing</h2>
    <p>Python</p>
    <MyproccessBar value={90}/>
    <p>C</p>
    <MyproccessBar value={75}/>
    <p>C++</p>
    <MyproccessBar value={92}/>
    <p>Java</p>
    <MyproccessBar value={30}/>
    </div>
    </>
    </div>
  )
}

function Projects(){
  return(
    <div className='Projects'>
    <>
    <h1>Selected Projects</h1>
    <p>Avoiding Traffic System With IoT</p>
    <p>Detection Dangerous items with AI</p>
    </>
    </div>
  )
}


function App() {
  return(
    <div className='App'>
    <>
    <h1>Giannis Stamoulakatos</h1>
    <p>AI,CyberSecyrity and IoT developer</p>
    <Skills />
    <Projects />
   <button>Contact Me</button>
    </>
    </div>
  )
}

export default App;
